type MultiSelectItem = {
  id: React.Key;
  [key: string]: unknown;
};

type MultiSelectItemOwnProps = {
  disabled?: boolean;
  textValue?: string;
};

type MultiSelectOwnProps<T extends MultiSelectItem = MultiSelectItem> = {
  size?: 'sm' | 'md' | 'lg';
  label?: React.ReactNode;
  placeholder?: string;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  disabled?: boolean;
  required?: boolean;
  invalid?: boolean;
  supportingText?: React.ReactNode;
  emptyStateTitle?: string;
  emptyStateDescription?: string;
  items?: Iterable<T>;
  selectedKeys?: Set<React.Key> | 'all';
  defaultSelectedKeys?: Set<React.Key>;
  onSelectionChange?: (keys: Set<React.Key> | 'all') => void;
  showSearch?: boolean;
  showFooter?: boolean;
  onReset?: () => void;
  onSelectAll?: () => void;
  selectedCountFormatter?: (count: number) => React.ReactNode;
};

type MultiSelectProps<T extends MultiSelectItem = MultiSelectItem> = Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> & MultiSelectOwnProps<T> & {
  children?: React.ReactNode | ((item: T) => React.ReactNode);
  readOnly?: boolean;
};

interface MultiSelectRootComponent {
  <T extends MultiSelectItem = MultiSelectItem>(props: MultiSelectRootProps<T> & React.RefAttributes<HTMLDivElement>): React.ReactElement | null;
}
